{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.beastlife_DOD_Hourly_Table_Query as WITH shopify_base AS ( SELECT Order_Date, FORMAT_TIME(\'%H:00:00\', TIME(order_time)) || \' - \' || FORMAT_TIME(\'%H:59:59\', TIME(order_time)) AS hour_range, cod_pp_flag, medium, source, channel, utm_campaign, utm_term, order_status, marketplace, customer_id, NAME, EMAIL, PHONE, pincode, ORDER_ID, order_name, SKU, PRODUCT_NAME, discount_codes, customer_segment, freebie_flag, new_customer_flag, app_website_flag, user_id, account_name, ad_name, adset_name, campaign_name, SUM(selling_price) AS selling_price, SUM(SHIPPING_PRICE) AS SHIPPING_PRICE, SUM(DISCOUNT) AS DISCOUNT, COUNT(DISTINCT ORDER_ID) AS total_orders, COUNT(DISTINCT CASE WHEN new_customer_flag = \'Repeat\' THEN ORDER_ID END)* 0.90 AS repeat_orders, COUNT(DISTINCT CASE WHEN new_customer_flag = \'New\' THEN ORDER_ID END)* 0.90 AS new_orders, SUM(CASE WHEN new_customer_flag = \'Repeat\' THEN selling_price END) * 0.90 AS repeat_sales, SUM(CASE WHEN new_customer_flag = \'New\' THEN selling_price END) * 0.90 AS new_sales, SUM( CASE WHEN Order_Date >= DATE \'2025-09-22\' THEN (selling_price / 1.06) * 0.90 ELSE (selling_price / 1.18) * 0.90 END ) AS NSV, SUM(selling_price) * 0.90 AS gross_sales, SUM(quantity) * 0.90 AS quantity FROM `beastlife-wh-474411.maplemonk.D2C_master` WHERE order_status = \'SHOPIFY_PROCESSED\' AND Order_Date <= CURRENT_DATE() - 3 GROUP BY Order_Date, hour_range, cod_pp_flag, medium, source, channel, utm_campaign, utm_term, order_status, marketplace, customer_id, NAME, EMAIL, PHONE, pincode, ORDER_ID, order_name, SKU, PRODUCT_NAME, discount_codes, customer_segment, freebie_flag, new_customer_flag, app_website_flag, user_id, account_name, ad_name, adset_name, campaign_name UNION ALL SELECT Order_Date, FORMAT_TIME(\'%H:00:00\', TIME(order_time)) || \' - \' || FORMAT_TIME(\'%H:59:59\', TIME(order_time)) AS hour_range, cod_pp_flag, medium, source, channel, utm_campaign, utm_term, order_status, marketplace, customer_id, NAME, EMAIL, PHONE, pincode, ORDER_ID, order_name, SKU, PRODUCT_NAME, discount_codes, customer_segment, freebie_flag, new_customer_flag, app_website_flag, user_id, account_name, ad_name, adset_name, campaign_name, SUM(selling_price) AS selling_price, SUM(SHIPPING_PRICE) AS SHIPPING_PRICE, SUM(DISCOUNT) AS DISCOUNT, COUNT(DISTINCT ORDER_ID) AS total_orders, COUNT(DISTINCT CASE WHEN new_customer_flag = \'Repeat\' THEN ORDER_ID END)* 0.90 AS repeat_orders, COUNT(DISTINCT CASE WHEN new_customer_flag = \'New\' THEN ORDER_ID END)* 0.90 AS new_orders, SUM(CASE WHEN new_customer_flag = \'Repeat\' THEN selling_price END) * 0.90 AS repeat_sales, SUM(CASE WHEN new_customer_flag = \'New\' THEN selling_price END) * 0.90 AS new_sales, SUM( CASE WHEN Order_Date >= DATE \'2025-09-22\' THEN (selling_price / 1.06) * 0.90 ELSE (selling_price / 1.18) * 0.90 END ) AS NSV, SUM(selling_price) * 0.90 AS gross_sales, SUM(quantity) * 0.90 AS quantity FROM `beastlife-wh-474411.maplemonk.Hourly_D2C_master` WHERE order_status = \'SHOPIFY_PROCESSED\' AND Order_Date > CURRENT_DATE() - 3 GROUP BY Order_Date, hour_range, cod_pp_flag, medium, source, channel, utm_campaign, utm_term, order_status, marketplace, customer_id, NAME, EMAIL, PHONE, pincode, ORDER_ID, order_name, SKU, PRODUCT_NAME, discount_codes, customer_segment, freebie_flag, new_customer_flag, app_website_flag, user_id, account_name, ad_name, adset_name, campaign_name ), catalog AS ( SELECT Category, SKU_Code, SKU_Type, Ingredients, Rev_Category, Sub_Category, Category_Type, Product_Name__as_on_Product_Packaging_, Flavour, SUM(CAST(MRP AS NUMERIC)) AS MRP, SUM(CAST(MRP_Revised AS NUMERIC)) AS MRP_Revised FROM `maplemonk.MasterCatalogue` GROUP BY 1,2,3,4,5,6,7,8,9 ), calendar AS ( SELECT PARSE_DATE(\'%Y-%m-%d\', event_date) AS event_date, Event, sub_event, FORMAT_DATE(\'%Y%m%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateAsInteger, FORMAT_DATE(\'%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateNumber, EXTRACT(YEAR FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS Year, FORMAT_DATE(\'%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNumber, FORMAT_DATE(\'%Y/%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthNumber, FORMAT_DATE(\'%Y/%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthShort, FORMAT_DATE(\'%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameShort, FORMAT_DATE(\'%B\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameLong, EXTRACT(DAYOFWEEK FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekNumber, FORMAT_DATE(\'%A\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeek, FORMAT_DATE(\'%a\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekShort, CONCAT(\'Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS Quarter, CONCAT( FORMAT_DATE(\'%Y\', PARSE_DATE(\'%Y-%m-%d\', event_date)), \'/Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING) ) AS YearQuarter, CASE WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 1 AND 7 THEN \'W1\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 8 AND 14 THEN \'W2\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 15 AND 21 THEN \'W3\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 22 AND 28 THEN \'W4\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) >= 29 THEN \'W5\' ELSE \'Error\' END AS WeekPeriod FROM `beastlife-wh-474411.maplemonk.beastlife_db_Calender` ), pincode AS ( SELECT City,Tier,Zone,State,Region,Post_Code,Zonal_Category FROM `beastlife-wh-474411.maplemonk.beastlife_db_PincodeMaster` ), cogs AS ( SELECT sku_code AS cogs_sku, product_name AS cogs_product_name, feb_cogs, nov_cogs, old_cogs, qtr_cogs, sept_2025_cogs, sept_2024_cogs, dec_2025_cogs, march_2026_cogs, may_2026_cogs FROM `beastlife-wh-474411.maplemonk.beastlife_db_COGS_data` ) SELECT sb.*, c.*, cal.*, p.*, CASE WHEN sb.Order_Date < DATE \'2024-09-01\' THEN CAST(cogs.old_cogs AS NUMERIC) * sb.quantity WHEN sb.Order_Date >= DATE \'2024-09-01\' AND sb.Order_Date < DATE \'2024-11-01\' THEN CAST(cogs.sept_2024_cogs AS NUMERIC) * sb.quantity WHEN sb.Order_Date >= DATE \'2024-11-01\' AND sb.Order_Date < DATE \'2025-02-01\' THEN CAST(cogs.nov_cogs AS NUMERIC) * sb.quantity WHEN sb.Order_Date >= DATE \'2025-02-01\' AND sb.Order_Date < DATE \'2025-09-01\' THEN CAST(cogs.feb_cogs AS NUMERIC) * sb.quantity WHEN sb.Order_Date >= DATE \'2025-09-01\' AND sb.Order_Date < DATE \'2025-12-01\' THEN CAST(cogs.sept_2025_cogs AS NUMERIC) * sb.quantity WHEN sb.Order_Date >= DATE \'2025-12-01\' AND sb.Order_Date < DATE \'2026-03-01\' THEN CAST(cogs.dec_2025_cogs AS NUMERIC) * sb.quantity WHEN sb.Order_Date >= DATE \'2026-03-01\' AND sb.Order_Date < DATE \'2026-05-01\' THEN CAST(cogs.march_2026_cogs AS NUMERIC) * sb.quantity WHEN sb.Order_Date >= DATE \'2026-05-01\' THEN CAST(cogs.may_2026_cogs AS NUMERIC) * sb.quantity ELSE NULL END AS COGS_Value FROM shopify_base sb LEFT JOIN catalog c ON sb.SKU = c.SKU_Code LEFT JOIN calendar cal ON sb.Order_Date = cal.event_date LEFT JOIN pincode p ON sb.pincode = p.Post_Code LEFT JOIN cogs cogs ON sb.SKU = cogs.cogs_sku;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            